with scored as (select *, lead(rating, 2, 0) over (partition by city, country order by rating, id) as next_rating, sum(rating) over (partition by city order by rating, id rows between unbounded preceding and current row) as running_rating from suppliers) select case when running_rating >= 15 then 'PREMIUM' else 'STANDARD' end as running_rating_tier, sort_array(collect_set(country)) as country_list, size(collect_set(country)) as num_countries, count(*) filter (where country = 'UK') as uk_rows from scored group by case when running_rating >= 15 then 'PREMIUM' else 'STANDARD' end
